using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using pet_project.Data; using pet_project.Models; namespace pet_project.Controllers;
public class PetsController:Controller { readonly AppDbContext c; public PetsController(AppDbContext c)=>this.c=c; public async Task<IActionResult> Index()=>View(await c.Pets.Include(x=>x.Shelter).ToListAsync()); public async Task<IActionResult> Details(int? id){if(id==null)return NotFound();var x=await c.Pets.Include(x=>x.Shelter).FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} public IActionResult Create()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Create([Bind("Id,Name,Species,Age,IsAvailable,ShelterId")]Pet x){if(!ModelState.IsValid)return View(x);c.Add(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Edit(int? id){if(id==null)return NotFound();var x=await c.Pets.FindAsync(id);return x==null?NotFound():View(x);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Edit(int id,[Bind("Id,Name,Species,Age,IsAvailable,ShelterId")]Pet x){if(id!=x.Id)return NotFound();if(!ModelState.IsValid)return View(x);c.Update(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Delete(int? id){if(id==null)return NotFound();var x=await c.Pets.Include(x=>x.Shelter).FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} [HttpPost,ActionName("Delete"),ValidateAntiForgeryToken] public async Task<IActionResult>DeleteConfirmed(int id){var x=await c.Pets.FindAsync(id);if(x!=null)c.Pets.Remove(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} }
